#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Modernized climate data analysis for Python 3.

This replaces the legacy Python 2.7 implementation while preserving its
station-by-station analysis workflow.
"""

from __future__ import annotations

import argparse
import configparser
from pathlib import Path

import pandas as pd

APP_DIR = Path(__file__).resolve().parent
LEGACY_DIR = APP_DIR / "climate_analyzer"
DEFAULT_CONFIG = LEGACY_DIR / "config.ini"
DEFAULT_DATA = LEGACY_DIR / "sample_data" / "climate_data.csv"


class ClimateAnalyzer:
    """Load climate observations and summarize them by station."""

    def __init__(self, config_path: Path | str | None = None) -> None:
        self.config = configparser.ConfigParser()
        if config_path is not None:
            config_path = Path(config_path)
            if config_path.is_file():
                self.config.read(config_path, encoding="utf-8")

    def load_temperature_data(self, filename: Path | str) -> pd.DataFrame:
        """Load a UTF-8 CSV file and parse its date column."""
        path = Path(filename)
        return pd.read_csv(path, encoding="utf-8", parse_dates=["date"])

    @staticmethod
    def calculate_anomalies(temperature_series: pd.Series) -> pd.Series:
        """Return deviations from the series mean using modern pandas APIs."""
        return temperature_series - temperature_series.mean()

    @staticmethod
    def station_mean_temperatures(data: pd.DataFrame) -> pd.Series:
        """Calculate the mean temperature for every station."""
        return data.groupby("station_id", sort=True)["temperature"].mean()

    def run_analysis(self, data_path: Path | str = DEFAULT_DATA) -> pd.Series:
        """Run the analysis and print one mean-temperature line per station."""
        data = self.load_temperature_data(data_path)
        means = self.station_mean_temperatures(data)

        for station_id, value in means.items():
            print(f"Station {station_id} mean temperature: {value:.1f}°C")

        return means


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Analyze climate station temperatures.")
    parser.add_argument(
        "--data",
        type=Path,
        default=DEFAULT_DATA,
        help=f"Path to the climate CSV file (default: {DEFAULT_DATA})",
    )
    parser.add_argument(
        "--config",
        type=Path,
        default=DEFAULT_CONFIG,
        help=f"Path to the configuration file (default: {DEFAULT_CONFIG})",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    analyzer = ClimateAnalyzer(config_path=args.config)
    analyzer.run_analysis(data_path=args.data)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
